CREATE DATABASE IF NOT EXISTS ppid_sukadana CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ppid_sukadana;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('SUPER_ADMIN','ADMIN_PPID','PETUGAS','VERIFIKATOR') NOT NULL DEFAULT 'PETUGAS', is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE public_information (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255) NOT NULL, category VARCHAR(80) NOT NULL, description TEXT, year SMALLINT NOT NULL, file_path VARCHAR(255), is_published TINYINT(1) NOT NULL DEFAULT 0, published_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(category), INDEX(year)) ENGINE=InnoDB;
CREATE TABLE information_requests (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, request_number VARCHAR(40) NOT NULL UNIQUE, nik VARCHAR(32), applicant_name VARCHAR(150) NOT NULL, address TEXT NOT NULL, phone VARCHAR(30) NOT NULL, email VARCHAR(190) NOT NULL, occupation VARCHAR(100), citizenship VARCHAR(80) DEFAULT 'Indonesia', information_type VARCHAR(120) NOT NULL, information_detail TEXT NOT NULL, purpose TEXT NOT NULL, acquisition_method VARCHAR(80) NOT NULL, copy_method VARCHAR(80) NOT NULL, status ENUM('Diajukan','Diverifikasi','Diproses','Menunggu Kelengkapan','Disetujui','Sebagian Disetujui','Ditolak','Selesai','Diajukan Keberatan') NOT NULL DEFAULT 'Diajukan', consent_at DATETIME NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(status), INDEX(email)) ENGINE=InnoDB;
CREATE TABLE request_status_histories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, request_id INT UNSIGNED NOT NULL, old_status VARCHAR(80), new_status VARCHAR(80) NOT NULL, note TEXT, changed_by INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(request_id) REFERENCES information_requests(id) ON DELETE CASCADE, FOREIGN KEY(changed_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE request_documents (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, request_id INT UNSIGNED NOT NULL, original_name VARCHAR(255) NOT NULL, stored_name VARCHAR(255) NOT NULL, mime_type VARCHAR(120) NOT NULL, file_size INT UNSIGNED NOT NULL, is_private TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(request_id) REFERENCES information_requests(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE objections (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, objection_number VARCHAR(40) NOT NULL UNIQUE, request_number VARCHAR(40) NOT NULL, applicant_name VARCHAR(150) NOT NULL, email VARCHAR(190) NOT NULL, reason VARCHAR(160) NOT NULL, description TEXT NOT NULL, status ENUM('Diajukan','Diverifikasi','Diproses','Dijawab','Selesai') DEFAULT 'Diajukan', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE news (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, excerpt TEXT, body LONGTEXT, category VARCHAR(80), is_published TINYINT(1) DEFAULT 0, published_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL, action VARCHAR(120) NOT NULL, entity_type VARCHAR(80), entity_id INT UNSIGNED NULL, metadata JSON NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
